<?php
require_once '../../includes/config/config.php';
require_once '../../includes/functions/functions.php';
require_once '../../includes/classes/StripeConnectService.php';
require_once '../../includes/classes/PaymentOrderRepository.php';
$payload=file_get_contents('php://input');$signature=$_SERVER['HTTP_STRIPE_SIGNATURE']??'';
try{
 $stripe=new StripeConnectService();$stripe->verifyWebhookSignature($payload,$signature,(string)STRIPE_WEBHOOK_SECRET);$event=json_decode($payload,true);if(!is_array($event)||empty($event['type'])||!isset($event['data']['object']))throw new RuntimeException('Evento Stripe inválido.');
 $supported=['checkout.session.completed','checkout.session.async_payment_succeeded','checkout.session.async_payment_failed','checkout.session.expired'];if(!in_array($event['type'],$supported,true)){http_response_code(200);echo json_encode(['received'=>true]);exit;}
 $session=$event['data']['object'];$orderId=(int)($session['metadata']['order_id']??$session['client_reference_id']??0);if($orderId<1)throw new RuntimeException('El webhook no contiene order_id.');$orders=new PaymentOrderRepository();$order=$orders->getOrderById($orderId);if(!$order)throw new RuntimeException('Pedido no encontrado: '.$orderId);
 $connectedAccount=(string)($event['account']??'');$expectedAccount=(string)($order['stripe_account_id']??'');if($connectedAccount!==''&&$expectedAccount!==''&&$connectedAccount!==$expectedAccount)throw new RuntimeException('La cuenta Stripe del webhook no coincide con el pedido.');
 if(in_array($event['type'],['checkout.session.expired','checkout.session.async_payment_failed'],true)){if(in_array(($order['status']??''),['fulfilled','cancelled'],true)){http_response_code(200);echo json_encode(['received'=>true]);exit;}$orders->releaseInventoryForOrder($orderId);$orders->markCancelled($orderId);http_response_code(200);echo json_encode(['received'=>true,'cancelled'=>true]);exit;}
 if(($order['status']??'')==='fulfilled'){http_response_code(200);echo json_encode(['received'=>true,'fulfilled'=>true]);exit;}if((string)($session['payment_status']??'')!=='paid'){http_response_code(200);echo json_encode(['received'=>true,'payment_pending'=>true]);exit;}
 $sessionId=(string)($session['id']??'');$paymentIntentId=(string)($session['payment_intent']??'');$orders->markPaid($orderId,$sessionId,$paymentIntentId);$orders->markFulfilling($orderId);$items=$orders->getItems($orderId);$fulfillToken=defined('PAYMENT_FULFILL_TOKEN')?(string)PAYMENT_FULFILL_TOKEN:'';$workerUrl=rtrim((string)(defined('D1_API_URL')?D1_API_URL:''),'/').'/api/payment/fulfill';if($fulfillToken===''||$workerUrl==='/api/payment/fulfill')throw new RuntimeException('Fulfillment interno no configurado.');
