 if($raw===false||$httpCode<200||$httpCode>=300){$message=$raw?:$curlError?:('Worker HTTP '.$httpCode);$orders->markFailed($orderId,$message);if($paymentIntentId!==''){try{$stripe->refundPaymentIntent($paymentIntentId,$expectedAccount);}catch(Throwable $refundError){qLog('[ERROR] Stripe refund failed: '.$refundError->getMessage());}}throw new RuntimeException('No se pudo completar la emisión. El pago será reembolsado.');}
